VRT_L("tle-d-svt-r56",R({"duree":20,"titre":"Pandémies et VIH/sida","accroche":"Un virus qui s'attaque aux défenseurs.","intro":"Une pandémie a des conséquences sanitaires et socioculturelles majeures.","objectifs":["expliquer l'action du VIH","interpréter une sérologie","lutter contre la stigmatisation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>pandémie</strong> est une épidémie qui s'étend à de très vastes territoires. Le <strong>VIH</strong> détruit progressivement les lymphocytes T4.</div>"},{"t":"La sérologie","verrou":true},{"t":"Conséquences et prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":56,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Dans un quartier de Douala, des voisins évitent une personne vivant avec le VIH.","tache":"Rédige un message pour lutter contre cette attitude."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-d-svt-r57",R({"duree":20,"titre":"Intégration : se protéger et protéger les autres","accroche":"Un vaccin, un dépistage, un geste barrière.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>L'<strong>immunité</strong> individuelle et les gestes collectifs limitent la propagation des maladies.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":57,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Au marché Mokolo, une rumeur affirme que les vaccins rendent malades.","tache":"Rédige un texte de 10 lignes pour rassurer et informer."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-d-svt-r58",R({"duree":20,"titre":"Testostérone et régulation chez l'homme","accroche":"Un thermostat hormonal.","intro":"La sécrétion de testostérone est contrôlée par l'axe hypothalamo-hypophysaire.","objectifs":["citer les rôles de la testostérone","décrire le contrôle","expliquer le rétrocontrôle"],"parties":[{"t":"La testostérone","html":"<div class='def'><b>Définition</b>La <strong>testostérone</strong> est l'hormone sexuelle mâle, sécrétée par les cellules de Leydig. Elle assure les caractères sexuels et participe à la spermatogenèse.</div>"},{"t":"Le contrôle","verrou":true},{"t":"Le rétrocontrôle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":58,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Après une ablation expérimentale de l'hypophyse chez un rat, le taux de testostérone chute.","tache":"Explique ce résultat."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-d-svt-r59",R({"duree":20,"titre":"Testostérone et complexe hypothalamo-hypophysaire","accroche":"Une expérience d'injection et de castration.","intro":"Des expériences montrent comment la testostérone agit sur le centre de commande.","objectifs":["interpréter une castration","interpréter une injection","conclure au rétrocontrôle"],"parties":[{"t":"Rétrocontrôle","html":"<div class='def'><b>Définition</b>Un <strong>rétrocontrôle négatif</strong> est l'action d'une hormone qui freine la sécrétion de l'organe qui la commande.</div>"},{"t":"Castration","verrou":true,"illus":{"legende":"Le complexe hypothalamo-hypophysaire et le rétrocontrôle de la testostérone.","ref":"feccd2be21b"}},{"t":"Injection","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":59,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Un jeune bodybuilder de Douala prend de la testostérone sans ordonnance.","tache":"Explique le risque pour sa fertilité."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-d-svt-r60",R({"duree":20,"titre":"Cycles sexuels de la femme","accroche":"Un calendrier en deux cycles couplés.","intro":"Chez la femme, l'ovaire et l'utérus évoluent de façon cyclique.","objectifs":["décrire le cycle ovarien","décrire le cycle utérin","repérer l'ovulation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>cycle sexuel</strong> dure environ 28 jours. Il couple un cycle ovarien et un cycle utérin.</div>"},{"t":"Cycle ovarien","verrou":true},{"t":"Cycle utérin","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":60,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Une élève de Tle à Bafia a un cycle régulier de 28 jours et veut comprendre son calendrier.","tache":"Situe l'ovulation."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-d-svt-r61",R({"duree":20,"titre":"Hormones ovariennes et rôle du complexe","accroche":"Œstrogènes et progestérone préparent la grossesse.","intro":"Les hormones ovariennes commandent l'utérus et sont elles-mêmes contrôlées.","objectifs":["citer les hormones","préciser leurs rôles","décrire le pic de LH"],"parties":[{"t":"Les hormones","html":"<div class='def'><b>Définition</b>Les <strong>œstrogènes</strong> sont sécrétés par les follicules. La <strong>progestérone</strong> est sécrétée par le corps jaune.</div>"},{"t":"Rôles","verrou":true,"illus":{"legende":"Le cycle sexuel de la femme : ovaire, hormones, utérus.","ref":"fab263da78a"}},{"t":"Le contrôle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":61,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Une femme de Kumba, qui désire un enfant, fait doser sa LH pendant un cycle de 28 jours : environ 10 UI/L la plupart du temps, puis 60 UI/L au 13ᵉ jour.","tache":"Interprète ce pic et indique la période la plus favorable à une grossesse."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-d-svt-r62",R({"duree":20,"titre":"Hormones ovariennes et complexe hypothalamo-hypophysaire","accroche":"Un frein, puis un accélérateur.","intro":"Selon la phase du cycle, le rétrocontrôle change de sens.","objectifs":["décrire les rétrocontrôles","expliquer le pic de LH","exploiter un document"],"parties":[{"t":"Les rétrocontrôles","html":"<div class='def'><b>Définition</b>Un taux faible d'œstrogènes exerce un <strong>rétrocontrôle négatif</strong>. Un taux élevé et prolongé exerce, avant l'ovulation, un <strong>rétrocontrôle positif</strong>.</div>"},{"t":"Pic de LH","verrou":true},{"t":"Phase lutéale","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":62,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Une enseignante de Yaoundé présente une courbe des hormones du cycle à sa classe.","tache":"Dis pourquoi la LH présente un pic."},"verrou":true,"nq":10,"labo":true}));
