VRT_L("tle-d-svt-r65",R({"duree":20,"titre":"Stérilité et infertilité","accroche":"Une difficulté qui touche les deux sexes.","intro":"L'infertilité d'un couple peut avoir des causes masculines, féminines ou mixtes.","objectifs":["citer des causes","citer des examens","refuser la stigmatisation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>infertilité</strong> est l'absence de grossesse après au moins un an de rapports réguliers non protégés.</div>"},{"t":"Causes","verrou":true},{"t":"Solutions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":65,"apc":{"module":"Santé reproductive, nutritionnelle et secourisme","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques et porter secours","situation":"Une femme à Bafoussam est accusée seule de ne pas avoir d'enfant.","tache":"Rédige un message pour la famille."},"verrou":true,"nq":10,"labo":true}));
